// Traditional C-style alias syntax
typedef unsigned int Count;
Count item_count = 5;

// Modern C++ (C++11) using syntax
using Index = size_t;
Index current_idx = 0;

// Alias for complex type (Function Pointer)
typedef void (*FP_Old)(int);
using FP_New = void (*)(int);

// *Crucial Advantage: Templated Aliases*
template <typename T>
struct Vector {};

// typedef cannot template the alias itself

template <typename T>
using Matrix = Vector<Vector<T>>;

Matrix<double> complex_data;
